namespace sv_f35e4fc41b3f47d091b4f32fc897a8d0.Services;

/// <summary>
/// Cascaded value representing the currently selected warehouse.
/// Registered via <see cref="CascadingValueSource{T}"/> so it crosses
/// the static-SSR → interactive render-mode boundary.
/// </summary>
public class WarehouseInfo
{
    public string WarehouseId { get; set; } = "WH-A";
    public string WarehouseName { get; set; } = "Warehouse A";

