@rendermode InteractiveServer
@using sv_f35e4fc41b3f47d091b4f32fc897a8d0.Services
@inject CascadingValueSource<WarehouseInfo> WarehouseSource

<div class="warehouse-selector px-3 py-2">
    <label class="form-label text-light mb-1" style="font-size: 0.8rem;">Current Warehouse</label>
    <select class="form-select form-select-sm"
            value="@_selectedId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseInfo.Available)
        {
            <option value="@wh.WarehouseId">@wh.WarehouseName</option>
        }
    </select>
</div>

@code {
    private string _selectedId = "WH-A";

    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    protected override void OnParametersSet()
    {
        if (Warehouse is not null)
            _selectedId = Warehouse.WarehouseId;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? "WH-A";
        var selected = WarehouseInfo.Available
            .FirstOrDefault(w => w.WarehouseId == _selectedId) ?? WarehouseInfo.Available[0];

        await WarehouseSource.NotifyChangedAsync(
            new WarehouseInfo
            {
                WarehouseId = selected.WarehouseId,
                WarehouseName = selected.WarehouseName
            });
    }
}

