@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private Action? _handler;
    private string? _pollingWarehouseId;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    protected override void OnParametersSet()
    {
        if (Warehouse is not null && Warehouse.WarehouseId != _pollingWarehouseId)
        {
            // Stop previous polling (if any) before starting for the new warehouse.
            if (_pollingWarehouseId is not null)
                AlertService.StopPolling();

            _pollingWarehouseId = Warehouse.WarehouseId;
            AlertService.StartPolling(Warehouse.WarehouseId);
        }
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        AlertService.StopPolling();
    }
}

