using sv_f35e4fc41b3f47d091b4f32fc897a8d0.Components;
using sv_f35e4fc41b3f47d091b4f32fc897a8d0.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Warehouse selection — CascadingValueSource crosses the static → interactive
// render-mode boundary that a plain <CascadingValue> in the layout would not.
builder.Services.AddCascadingValue(sp =>
{
    var initial = new WarehouseInfo { WarehouseId = "WH-A", WarehouseName = "Warehouse A" };
    return new CascadingValueSource<WarehouseInfo>(initial, isFixed: false);
});

// Scoped so each user circuit gets its own independent alert counts.
builder.Services.AddScoped<InventoryAlertService>();

